  if (!licenseKeyUsable()) { noteFailed(); return deny(); }

  if (Date.now() - lastVerifiedAt() < B1S_VERIFY_CACHE_MS) return allow(); // cache 7 ngày
  if (Date.now() - memOkAt < B1S_MEM_OK_MS) return allow();               // cache 6 giờ trong bộ nhớ

