      try { console.log("[locketgold] " + T + ": verify FAIL (device=" + id.slice(0, 12) + "…)"); } catch (e) {}
      if (offlineGraceActive()) {
        try { console.log("[locketgold] " + T + ": OFFLINE-GRACE"); } catch (e) {}
        return allow();
      }
      noteFailed();
      memFailAt = Date.now();
      return deny();
